[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Frontier AI Models Compared - Infographic</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2400px;
    height: 3400px;
    background: #0c0e14;
    color: #e2e8f0;
    font-family: 'Inter', -apple-system, sans-serif;
    overflow: hidden;
    position: relative;
  }

  .poster {
    width: 100%;
    height: 100%;
    padding: 64px 72px;
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
  }

  /* Subtle grid background */
  .poster::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(rgba(59,130,246,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(59,130,246,0.03) 1px, transparent 1px);
    background-size: 60px 60px;
    pointer-events: none;
  }

  /* ---- HEADER ---- */
  .header {
    position: relative;
    padding-bottom: 40px;
    border-bottom: 1px solid #1e2536;
  }

  .header-top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 36px;
  }

  .title-group h1 {
    font-size: 52px;
    font-weight: 800;
    letter-spacing: -1.5px;
    line-height: 1.1;
    background: linear-gradient(135deg, #f1f5f9 0%, #94a3b8 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .title-group .subtitle {
    font-size: 26px;
    font-weight: 300;
    color: #64748b;
    margin-top: 8px;
    letter-spacing: 3px;
    text-transform: uppercase;
  }

  .source-badge {
    background: rgba(59,130,246,0.1);
    border: 1px solid rgba(59,130,246,0.25);
    border-radius: 8px;
    padding: 12px 20px;
    font-size: 15px;
    color: #60a5fa;
    font-weight: 500;
    white-space: nowrap;
  }

  /* ---- STAT CARDS ---- */
  .stat-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
  }

  .stat-card {
    background: linear-gradient(135deg, #151821 0%, #1a1f2e 100%);
    border: 1px solid #1e2536;
    border-radius: 16px;
    padding: 24px 28px;
    position: relative;
    overflow: hidden;
  }

  .stat-card::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }

  .stat-card.blue::after { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
  .stat-card.teal::after { background: linear-gradient(90deg, #06b6d4, #22d3ee); }
  .stat-card.amber::after { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
  .stat-card.red::after { background: linear-gradient(90deg, #ef4444, #f87171); }

  .stat-card .stat-value {
    font-size: 52px;
    font-weight: 900;
    letter-spacing: -2px;
    line-height: 1;
  }

  .stat-card.blue .stat-value { color: #60a5fa; }
  .stat-card.teal .stat-value { color: #22d3ee; }
  .stat-card.amber .stat-value { color: #fbbf24; }
  .stat-card.red .stat-value { color: #f87171; }

  .stat-card .stat-unit {
    font-size: 18px;
    font-weight: 500;
    color: #64748b;
    margin-top: 4px;
  }

  .stat-card .stat-label {
    font-size: 14px;
    font-weight: 400;
    color: #475569;
    margin-top: 8px;
    line-height: 1.4;
  }

  /* ---- SECTIONS ---- */
  .section {
    position: relative;
    padding: 36px 0;
    border-bottom: 1px solid #1e2536;
  }

  .section-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 28px;
  }

  .section-title {
    font-size: 28px;
    font-weight: 700;
    letter-spacing: -0.5px;
    color: #f1f5f9;
  }

  .section-badge {
    font-size: 13px;
    font-weight: 600;
    padding: 5px 14px;
    border-radius: 20px;
    letter-spacing: 0.5px;
  }

  .badge-insight {
    background: rgba(6,182,212,0.15);
    color: #22d3ee;
    border: 1px solid rgba(6,182,212,0.3);
  }

  .badge-warning {
    background: rgba(245,158,11,0.15);
    color: #fbbf24;
    border: 1px solid rgba(245,158,11,0.3);
  }

  .section-desc {
    font-size: 16px;
    color: #64748b;
    margin-bottom: 24px;
    line-height: 1.5;
  }

  /* ---- BAR CHART ---- */
  .bar-chart {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .bar-row {
    display: grid;
    grid-template-columns: 200px 1fr 80px;
    align-items: center;
    gap: 16px;
    height: 32px;
  }

  .bar-label {
    font-size: 14px;
    font-weight: 500;
    color: #cbd5e1;
    text-align: right;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .bar-track {
    height: 24px;
    background: rgba(255,255,255,0.03);
    border-radius: 4px;
    overflow: hidden;
    position: relative;
  }

  .bar-fill {
    height: 100%;
    border-radius: 4px;
    position: relative;
    transition: width 0.3s ease;
  }

  .bar-fill.blue { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
  .bar-fill.teal { background: linear-gradient(90deg, #0891b2, #22d3ee); }
  .bar-fill.amber { background: linear-gradient(90deg, #d97706, #fbbf24); }

  .bar-fill.highlight {
    box-shadow: 0 0 20px rgba(59,130,246,0.3);
  }

  .bar-value {
    font-size: 15px;
    font-weight: 700;
    color: #f1f5f9;
    text-align: left;
  }

  /* ---- HERO: BUBBLE CHART ---- */
  .hero-section {
    padding: 40px 0;
    border-bottom: 1px solid #1e2536;
    flex: 1;
  }

  .hero-section .section-title {
    font-size: 34px;
    margin-bottom: 8px;
  }

  .bubble-chart-container {
    position: relative;
    width: 100%;
    margin-top: 20px;
  }

  .bubble-chart-svg {
    width: 100%;
    height: 100%;
  }

  .insight-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin-top: 28px;
  }

  .insight-card {
    background: rgba(255,255,255,0.03);
    border: 1px solid #1e2536;
    border-radius: 12px;
    padding: 20px;
    position: relative;
  }

  .insight-card .insight-tag {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
  }

  .insight-card .insight-tag.blue { color: #60a5fa; }
  .insight-card .insight-tag.teal { color: #22d3ee; }
  .insight-card .insight-tag.amber { color: #fbbf24; }
  .insight-card .insight-tag.green { color: #34d399; }

  .insight-card .insight-title {
    font-size: 17px;
    font-weight: 700;
    color: #f1f5f9;
    margin-bottom: 6px;
  }

  .insight-card .insight-desc {
    font-size: 13px;
    color: #64748b;
    line-height: 1.5;
  }

  /* ---- METHODOLOGY ---- */
  .methodology {
    padding: 32px 0 16px;
  }

  .methodology-title {
    font-size: 16px;
    font-weight: 600;
    color: #475569;
    margin-bottom: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .methodology-text {
    font-size: 13px;
    color: #334155;
    line-height: 1.7;
    max-width: 1600px;
  }

  .methodology-text span {
    color: #475569;
  }

  /* ---- FOOTER ---- */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 16px;
    border-top: 1px solid #111520;
  }

  .footer-text {
    font-size: 12px;
    color: #1e293b;
  }

  /* Axis labels for bubble chart */
  .axis-label {
    font-family: 'Inter', sans-serif;
    font-size: 13px;
    fill: #475569;
    font-weight: 500;
  }

  .axis-title {
    font-family: 'Inter', sans-serif;
    font-size: 15px;
    fill: #64748b;
    font-weight: 600;
  }

  .grid-line {
    stroke: #1e2536;
    stroke-width: 1;
    stroke-dasharray: 4,4;
  }

  .bubble-label {
    font-family: 'Inter', sans-serif;
    font-size: 11px;
    fill: #cbd5e1;
    font-weight: 500;
  }

  .bubble-value-label {
    font-family: 'Inter', sans-serif;
    font-size: 10px;
    fill: #64748b;
    font-weight: 400;
  }

  .price-legend {
    font-family: 'Inter', sans-serif;
    font-size: 12px;
    fill: #64748b;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-top">
      <div class="title-group">
        <h1>Frontier AI Models Compared</h1>
        <div class="subtitle">Intelligence &middot; Speed &middot; Cost</div>
      </div>
      <div class="source-badge">Artificial Analysis Intelligence Index v4.0</div>
    </div>
    <div class="stat-cards">
      <div class="stat-card blue">
        <div class="stat-value">57</div>
        <div class="stat-unit">AA Index</div>
        <div class="stat-label">Top intelligence score &mdash; Gemini 3.1 Pro &amp; GPT-5.4 tied</div>
      </div>
      <div class="stat-card teal">
        <div class="stat-value">206</div>
        <div class="stat-unit">tokens/sec</div>
        <div class="stat-label">Fastest output speed &mdash; gpt-oss-120B leads throughput</div>
      </div>
      <div class="stat-card amber">
        <div class="stat-value">$0.30&ndash;$10</div>
        <div class="stat-unit">per 1M tokens</div>
        <div class="stat-label">Price range from cheapest to most expensive model</div>
      </div>
      <div class="stat-card red">
        <div class="stat-value">33&times;</div>
        <div class="stat-unit">price factor</div>
        <div class="stat-label">Cheapest model costs 33&times; less than the priciest</div>
      </div>
    </div>
  </div>

  <!-- INTELLIGENCE RANKINGS -->
  <div class="section">
    <div class="section-header">
      <div class="section-title">Intelligence Rankings</div>
    </div>
    <div class="section-desc">Aggregated scores across 10 evaluations covering coding, agentic tasks, knowledge, and reasoning. A 24-point gap separates the leaders from the budget tier.</div>
    <div class="bar-chart" id="intelligence-chart"></div>
  </div>

  <!-- SPEED COMPARISON -->
  <div class="section">
    <div class="section-header">
      <div class="section-title">Output Speed Comparison</div>
      <div class="section-badge badge-insight">Speed &ne; Intelligence</div>
    </div>
    <div class="section-desc">Tokens per second &mdash; the fastest models are not the most intelligent. Budget-tier gpt-oss-120B leads at 206 tok/s, nearly 7&times; faster than DeepSeek V3.2.</div>
    <div class="bar-chart" id="speed-chart"></div>
  </div>

  <!-- PRICING LANDSCAPE -->
  <div class="section">
    <div class="section-header">
      <div class="section-title">Pricing Landscape</div>
      <div class="section-badge badge-warning">33&times; Price Range</div>
    </div>
    <div class="section-desc">USD per 1M tokens (blended input/output). Premium intelligence comes at a steep premium &mdash; Claude Opus 4.6 costs 33&times; more than the cheapest options.</div>
    <div class="bar-chart" id="pricing-chart"></div>
  </div>

  <!-- TRADE-OFF ANALYSIS (HERO) -->
  <div class="hero-section">
    <div class="section-header">
      <div class="section-title">The Intelligence&ndash;Speed&ndash;Cost Trade-Off</div>
    </div>
    <div class="section-desc">Position = intelligence (x) &amp; speed (y). Bubble size = price (larger = more expensive). No single model dominates all three dimensions.</div>
    <div class="bubble-chart-container">
      <svg id="bubble-chart" class="bubble-chart-svg" viewBox="0 0 2200 560"></svg>
    </div>
    <div class="insight-cards">
      <div class="insight-card">
        <div class="insight-tag blue">Best Intelligence</div>
        <div class="insight-title">Gemini 3.1 Pro &amp; GPT-5.4</div>
        <div class="insight-desc">Tied at 57 AA Index, but mid-to-high cost ($4.50&ndash;$5.60). Neither is the fastest.</div>
      </div>
      <div class="insight-card">
        <div class="insight-tag amber">Best Value</div>
        <div class="insight-title">gpt-oss-120B</div>
        <div class="insight-desc">Fastest speed (206 tok/s) and lowest price ($0.30), but ranks last in intelligence (33).</div>
      </div>
      <div class="insight-card">
        <div class="insight-tag teal">Balanced Pick</div>
        <div class="insight-title">Gemini 3 Flash</div>
        <div class="insight-desc">Score 46 intelligence, 149 tok/s speed, just $1.10 &mdash; a strong middle ground across all dimensions.</div>
      </div>
      <div class="insight-card">
        <div class="insight-tag green">Premium Tier</div>
        <div class="insight-title">Claude Opus 4.6</div>
        <div class="insight-desc">Delivers 53 intelligence but is the slowest (40 tok/s) and most expensive ($10.00).</div>
      </div>
    </div>
  </div>

  <!-- METHODOLOGY -->
  <div class="methodology">
    <div class="methodology-title">About the Index</div>
    <div class="methodology-text">
      The Artificial Analysis Intelligence Index v4.0 incorporates <span>10 independent evaluations</span>: GDPval-AA, &tau;&sup2;-Bench Telecom, Terminal-Bench Hard, SciCode, AA-LCR, AA-Omniscience, IFBench, Humanity's Last Exam, GPQA Diamond, and CritPt. These span <span>coding, agentic tasks, scientific reasoning, knowledge accuracy, hallucination resistance, and instruction following</span>. All measurements are conducted independently by Artificial Analysis using standardized conditions. Pricing reflects blended input/output rates as of the index publication date.
    </div>
  </div>

  <!-- FOOTER -->
  <div class="footer">
    <div class="footer-text">Data: artificialanalysis.ai &middot; Artificial Analysis Intelligence Index v4.0</div>
    <div class="footer-text">There is no single &ldquo;best&rdquo; model &mdash; the right choice depends on which dimension matters most.</div>
  </div>

</div>

<script>
// Data
const models = [
  { name: 'Gemini 3.1 Pro', full: 'Gemini 3.1 Pro Preview', intel: 57, speed: 129, price: 4.50 },
  { name: 'GPT-5.4', full: 'GPT-5.4 (xhigh)', intel: 57, speed: 72, price: 5.60 },
  { name: 'Claude Opus 4.6', full: 'Claude Opus 4.6 (max)', intel: 53, speed: 40, price: 10.00 },
  { name: 'Muse Spark', full: 'Muse Spark', intel: 52, speed: 0, price: 0 },
  { name: 'Claude Sonnet 4.6', full: 'Claude Sonnet 4.6 (max)', intel: 52, speed: 48, price: 6.00 },
  { name: 'GLM-5.1', full: 'GLM-5.1', intel: 51, speed: 40, price: 2.10 },
  { name: 'Grok 4.20', full: 'Grok 4.20 0309 v2', intel: 49, speed: 162, price: 3.00 },
  { name: 'Gemini 3 Flash', full: 'Gemini 3 Flash', intel: 46, speed: 149, price: 1.10 },
  { name: 'DeepSeek V3.2', full: 'DeepSeek V3.2', intel: 42, speed: 31, price: 0.30 },
  { name: 'Nemotron 3', full: 'NVIDIA Nemotron 3 Super', intel: 36, speed: 193, price: 0.40 },
  { name: 'gpt-oss-120B', full: 'gpt-oss-120B (high)', intel: 33, speed: 206, price: 0.30 }
];

// ---- BAR CHART RENDERER ----
function renderBarChart(containerId, data, maxVal, colorClass, formatFn) {
  const container = document.getElementById(containerId);
  let html = '';
  data.forEach((item, i) => {
    const pct = (item.value / maxVal) * 100;
    const highlight = i < 2 ? ' highlight' : '';
    html += `
      <div class="bar-row">
        <div class="bar-label">${item.label}</div>
        <div class="bar-track">
          <div class="bar-fill ${colorClass}${highlight}" style="width:${pct}%"></div>
        </div>
        <div class="bar-value">${formatFn(item.value)}</div>
      </div>`;
  });
  container.innerHTML = html;
}

// Intelligence chart
const intelData = models.map(m => ({ label: m.name, value: m.intel }));
renderBarChart('intelligence-chart', intelData, 60, 'blue', v => v);

// Speed chart (exclude Muse Spark which has no speed data)
const speedModels = models.filter(m => m.speed > 0);
const speedData = speedModels.map(m => ({ label: m.name, value: m.speed }));
renderBarChart('speed-chart', speedData, 220, 'teal', v => v + ' tok/s');

// Pricing chart
const pricingModels = models.filter(m => m.price > 0).sort((a, b) => a.price - b.price);
const pricingData = pricingModels.map(m => ({ label: m.name, value: m.price }));
renderBarChart('pricing-chart', pricingData, 11, 'amber', v => '$' + v.toFixed(2));

// ---- BUBBLE CHART (HERO) ----
(function() {
  const svg = document.getElementById('bubble-chart');
  const margin = { top: 30, right: 80, bottom: 50, left: 60 };
  const width = 2200 - margin.left - margin.right;
  const height = 560 - margin.top - margin.bottom;

  const bubbleModels = models.filter(m => m.speed > 0 && m.price > 0);

  const xMin = 28, xMax = 62;
  const yMin = 0, yMax = 230;
  const priceMin = 0, priceMax = 11;

  function scaleX(v) { return margin.left + ((v - xMin) / (xMax - xMin)) * width; }
  function scaleY(v) { return margin.top + height - ((v - yMin) / (yMax - yMin)) * height; }
  function scaleR(p) { return 8 + (p / priceMax) * 32; }

  let svgContent = '';

  // Grid lines
  for (let x = 30; x <= 60; x += 5) {
    const px = scaleX(x);
    svgContent += `<line x1="${px}" y1="${margin.top}" x2="${px}" y2="${margin.top + height}" class="grid-line"/>`;
    svgContent += `<text x="${px}" y="${margin.top + height + 22}" class="axis-label" text-anchor="middle">${x}</text>`;
  }
  for (let y = 0; y <= 200; y += 50) {
    const py = scaleY(y);
    svgContent += `<line x1="${margin.left}" y1="${py}" x2="${margin.left + width}" y2="${py}" class="grid-line"/>`;
    svgContent += `<text x="${margin.left - 12}" y="${py + 5}" class="axis-label" text-anchor="end">${y}</text>`;
  }

  // Axis titles
  svgContent += `<text x="${margin.left + width / 2}" y="${margin.top + height + 44}" class="axis-title" text-anchor="middle">Intelligence Score (AA Index)</text>`;
  svgContent += `<text x="18" y="${margin.top + height / 2}" class="axis-title" text-anchor="middle" transform="rotate(-90, 18, ${margin.top + height / 2})">Output Speed (tokens/sec)</text>`;

  // Color mapping
  function getColor(m) {
    if (m.intel >= 53) return '#3b82f6';
    if (m.intel >= 46 && m.speed >= 100) return '#06b6d4';
    if (m.intel >= 46) return '#8b5cf6';
    if (m.price <= 0.50) return '#f59e0b';
    return '#10b981';
  }

  function getGlow(m) {
    if (m.intel >= 53) return 'rgba(59,130,246,0.3)';
    if (m.intel >= 46 && m.speed >= 100) return 'rgba(6,182,212,0.3)';
    if (m.intel >= 46) return 'rgba(139,92,246,0.3)';
    if (m.price <= 0.50) return 'rgba(245,158,11,0.3)';
    return 'rgba(16,185,129,0.3)';
  }

  // Bubbles
  bubbleModels.forEach(m => {
    const cx = scaleX(m.intel);
    const cy = scaleY(m.speed);
    const r = scaleR(m.price);
    const color = getColor(m);
    const glow = getGlow(m);

    // Glow
    svgContent += `<circle cx="${cx}" cy="${cy}" r="${r + 6}" fill="${glow}" opacity="0.5"/>`;
    // Circle
    svgContent += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${color}" opacity="0.75" stroke="${color}" stroke-width="2"/>`;
    // Inner highlight
    svgContent += `<circle cx="${cx}" cy="${cy}" r="${r * 0.6}" fill="white" opacity="0.08"/>`;

    // Label
    const labelY = cy - r - 10;
    svgContent += `<text x="${cx}" y="${labelY}" class="bubble-label" text-anchor="middle" font-weight="600">${m.name}</text>`;
    svgContent += `<text x="${cx}" y="${labelY + 14}" class="bubble-value-label" text-anchor="middle">Int:${m.intel} · ${m.speed}tok/s · $${m.price.toFixed(2)}</text>`;
  });

  // Price size legend
  const legendX = margin.left + width - 120;
  const legendY = margin.top + 20;
  svgContent += `<text x="${legendX}" y="${legendY}" class="price-legend" font-weight="600">Price (bubble size)</text>`;
  [0.30, 3.0, 10.0].forEach((p, i) => {
    const r = scaleR(p);
    const cy = legendY + 30 + i * 50;
    svgContent += `<circle cx="${legendX + 20}" cy="${cy}" r="${r}" fill="none" stroke="#475569" stroke-width="1" stroke-dasharray="3,3"/>`;
    svgContent += `<text x="${legendX + 50}" y="${cy + 5}" class="price-legend">$${p.toFixed(2)}</text>`;
  });

  svg.innerHTML = svgContent;
})();
</script>
</body>
</html>
