  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Set viewport to match poster dimensions
  await page.setViewportSize({ width: 2400, height: 3400 });

  // Load the HTML file
  const filePath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${filePath}`, { waitUntil: 'networkidle' });

  // Wait for fonts and rendering to complete
  await page.waitForTimeout(2000);

  // Take a full-page screenshot
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: false,
    type: 'png'
  });

  console.log('Screenshot saved to /app/output/final_poster.png');
  await browser.close();
})();

