const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 2400, height: 3400 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Check font rendering
  const fontInfo = await page.evaluate(() => {
    const h1 = document.querySelector('h1');
    const computed = window.getComputedStyle(h1);
    return {
      fontFamily: computed.fontFamily,
      fontSize: computed.fontSize,
      titleText: h1.textContent
    };
  });
  console.log('Font info:', JSON.stringify(fontInfo));

  // Check if content overflows
  const overflow = await page.evaluate(() => {
    const poster = document.querySelector('.poster');
    return {
      scrollHeight: poster.scrollHeight,
      clientHeight: poster.clientHeight,
      bodyScroll: document.body.scrollHeight,
      bodyClient: document.body.clientHeight
    };
  });
  console.log('Overflow info:', JSON.stringify(overflow));

  // Check bubble chart dimensions
  const bubbleInfo = await page.evaluate(() => {
    const svg = document.getElementById('bubble-chart');
    return {
      viewBox: svg.getAttribute('viewBox'),
      width: svg.clientWidth,
      height: svg.clientHeight
    };
  });
  console.log('Bubble chart:', JSON.stringify(bubbleInfo));

  await browser.close();
})();
"

