505	<script>
506	// Data
507	const models = [
508	  { name: 'Gemini 3.1 Pro', full: 'Gemini 3.1 Pro Preview', intel: 57, speed: 129, price: 4.50 },
509	  { name: 'GPT-5.4', full: 'GPT-5.4 (xhigh)', intel: 57, speed: 72, price: 5.60 },
510	  { name: 'Claude Opus 4.6', full: 'Claude Opus 4.6 (max)', intel: 53, speed: 40, price: 10.00 },
511	  { name: 'Muse Spark', full: 'Muse Spark', intel: 52, speed: 0, price: 0 },
512	  { name: 'Claude Sonnet 4.6', full: 'Claude Sonnet 4.6 (max)', intel: 52, speed: 48, price: 6.00 },
513	  { name: 'GLM-5.1', full: 'GLM-5.1', intel: 51, speed: 40, price: 2.10 },
514	  { name: 'Grok 4.20', full: 'Grok 4.20 0309 v2', intel: 49, speed: 162, price: 3.00 },
515	  { name: 'Gemini 3 Flash', full: 'Gemini 3 Flash', intel: 46, speed: 149, price: 1.10 },
516	  { name: 'DeepSeek V3.2', full: 'DeepSeek V3.2', intel: 42, speed: 31, price: 0.30 },
517	  { name: 'Nemotron 3', full: 'NVIDIA Nemotron 3 Super', intel: 36, speed: 193, price: 0.40 },
518	  { name: 'gpt-oss-120B', full: 'gpt-oss-120B (high)', intel: 33, speed: 206, price: 0.30 }
519	];
520	
521	// ---- BAR CHART RENDERER ----
522	function renderBarChart(containerId, data, maxVal, colorClass, formatFn) {
523	  const container = document.getElementById(containerId);
524	  let html = '';
525	  data.forEach((item, i) => {
526	    const pct = (item.value / maxVal) * 100;
527	    const highlight = i < 2 ? ' highlight' : '';
528	    html += `
529	      <div class="bar-row">
530	        <div class="bar-label">${item.label}</div>
531	        <div class="bar-track">
532	          <div class="bar-fill ${colorClass}${highlight}" style="width:${pct}%"></div>
533	        </div>
534	        <div class="bar-value">${formatFn(item.value)}</div>
535	      </div>`;
536	  });
537	  container.innerHTML = html;
538	}
539	
540	// Intelligence chart
541	const intelData = models.map(m => ({ label: m.name, value: m.intel }));
542	renderBarChart('intelligence-chart', intelData, 60, 'blue', v => v);
543	
544	// Speed chart (exclude Muse Spark which has no speed data)
545	const speedModels = models.filter(m => m.speed > 0);
546	const speedData = speedModels.map(m => ({ label: m.name, value: m.speed }));
547	renderBarChart('speed-chart', speedData, 220, 'teal', v => v + ' tok/s');
548	
549	// Pricing chart
550	const pricingModels = models.filter(m => m.price > 0).sort((a, b) => a.price - b.price);
551	const pricingData = pricingModels.map(m => ({ label: m.name, value: m.price }));
552	renderBarChart('pricing-chart', pricingData, 11, 'amber', v => '$' + v.toFixed(2));
553	
554	// ---- BUBBLE CHART (HERO) ----
555	(function() {
556	  const svg = document.getElementById('bubble-chart');
557	  const margin = { top: 30, right: 80, bottom: 50, left: 60 };
558	  const width = 2200 - margin.left - margin.right;
559	  const height = 560 - margin.top - margin.bottom;
560	
561	  const bubbleModels = models.filter(m => m.speed > 0 && m.price > 0);
562	
563	  const xMin = 28, xMax = 62;
564	  const yMin = 0, yMax = 230;
565	  const priceMin = 0, priceMax = 11;
566	
567	  function scaleX(v) { return margin.left + ((v - xMin) / (xMax - xMin)) * width; }
568	  function scaleY(v) { return margin.top + height - ((v - yMin) / (yMax - yMin)) * height; }
569	  function scaleR(p) { return 8 + (p / priceMax) * 32; }
570	
571	  let svgContent = '';
572	
573	  // Grid lines
574	  for (let x = 30; x <= 60; x += 5) {
575	    const px = scaleX(x);
576	    svgContent += `<line x1="${px}" y1="${margin.top}" x2="${px}" y2="${margin.top + height}" class="grid-line"/>`;
577	    svgContent += `<text x="${px}" y="${margin.top + height + 22}" class="axis-label" text-anchor="middle">${x}</text>`;
578	  }
579	  for (let y = 0; y <= 200; y += 50) {
580	    const py = scaleY(y);
581	    svgContent += `<line x1="${margin.left}" y1="${py}" x2="${margin.left + width}" y2="${py}" class="grid-line"/>`;
582	    svgContent += `<text x="${margin.left - 12}" y="${py + 5}" class="axis-label" text-anchor="end">${y}</text>`;
583	  }
584	
585	  // Axis titles
586	  svgContent += `<text x="${margin.left + width / 2}" y="${margin.top + height + 44}" class="axis-title" text-anchor="middle">Intelligence Score (AA Index)</text>`;
587	  svgContent += `<text x="18" y="${margin.top + height / 2}" class="axis-title" text-anchor="middle" transform="rotate(-90, 18, ${margin.top + height / 2})">Output Speed (tokens/sec)</text>`;
588	
589	  // Color mapping
590	  function getColor(m) {
591	    if (m.intel >= 53) return '#3b82f6';
592	    if (m.intel >= 46 && m.speed >= 100) return '#06b6d4';
593	    if (m.intel >= 46) return '#8b5cf6';
594	    if (m.price <= 0.50) return '#f59e0b';
595	    return '#10b981';
596	  }
597	
598	  function getGlow(m) {
599	    if (m.intel >= 53) return 'rgba(59,130,246,0.3)';
600	    if (m.intel >= 46 && m.speed >= 100) return 'rgba(6,182,212,0.3)';
601	    if (m.intel >= 46) return 'rgba(139,92,246,0.3)';
602	    if (m.price <= 0.50) return 'rgba(245,158,11,0.3)';
603	    return 'rgba(16,185,129,0.3)';
604	  }
605	
606	  // Bubbles
607	  bubbleModels.forEach(m => {
608	    const cx = scaleX(m.intel);
609	    const cy = scaleY(m.speed);
610	    const r = scaleR(m.price);
611	    const color = getColor(m);
612	    const glow = getGlow(m);
613	
614	    // Glow
615	    svgContent += `<circle cx="${cx}" cy="${cy}" r="${r + 6}" fill="${glow}" opacity="0.5"/>`;
616	    // Circle
617	    svgContent += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${color}" opacity="0.75" stroke="${color}" stroke-width="2"/>`;
618	    // Inner highlight
