function renderBarChart(containerId, data, maxVal, colorClass, formatFn) {
  const container = document.getElementById(containerId);
  let html = '';
  data.forEach((item, i) => {
    const pct = (item.value / maxVal) * 100;
    const topClass = i === 0 ? ' top1' : i === 1 ? ' top2' : '';
    html += `
      <div class="bar-row">
        <div class="bar-label">${item.label}</div>
        <div class="bar-track">
          <div class="bar-fill ${colorClass}${topClass}" style="width:${pct}%"></div>
        </div>
        <div class="bar-value">${formatFn(item.value)}</div>
      </div>`;
  });
  container.innerHTML = html;
}

// Intelligence chart
const intelData = models.map(m => ({ label: m.name, value: m.intel }));
renderBarChart('intelligence-chart', intelData, 60, 'blue', v => v);

// Speed chart
const speedModels = models.filter(m => m.speed > 0);
const speedData = speedModels.map(m => ({ label: m.name, value: m.speed }));
renderBarChart('speed-chart', speedData, 220, 'teal', v => v + ' tok/s');

// Pricing chart
const pricingModels = models.filter(m => m.price > 0).sort((a, b) => a.price - b.price);
const pricingData = pricingModels.map(m => ({ label: m.name, value: m.price }));
renderBarChart('pricing-chart', pricingData, 11, 'amber', v => '$' + v.toFixed(2));

// ---- BUBBLE CHART (HERO) ----
(function() {
  const svg = document.getElementById('bubble-chart');
  const rect = svg.getBoundingClientRect();
  const W = rect.width || 2200;
  const H = rect.height || 560;

  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);

  const margin = { top: 40, right: 100, bottom: 55, left: 65 };
  const w = W - margin.left - margin.right;
  const h = H - margin.top - margin.bottom;

  const bubbleModels = models.filter(m => m.speed > 0 && m.price > 0);

  const xMin = 28, xMax = 62;
  const yMin = 0, yMax = 230;

  function scaleX(v) { return margin.left + ((v - xMin) / (xMax - xMin)) * w; }
  function scaleY(v) { return margin.top + h - ((v - yMin) / (yMax - yMin)) * h; }
  function scaleR(p) { return 10 + (p / 11) * 34; }

  let s = '';

  // Zone backgrounds
  // Top-right: Smart & Fast
  s += `<rect x="${scaleX(45)}" y="${scaleY(230)}" width="${scaleX(62)-scaleX(45)}" height="${scaleY(80)-scaleY(230)}" fill="rgba(59,130,246,0.02)" rx="4"/>`;
  s += `<text x="${scaleX(53.5)}" y="${scaleY(220)}" class="zone-label" text-anchor="middle">Smart &amp; Fast</text>`;

  // Bottom-left: Budget
  s += `<rect x="${scaleX(28)}" y="${scaleY(80)}" width="${scaleX(45)-scaleX(28)}" height="${scaleY(0)-scaleY(80)}" fill="rgba(245,158,11,0.02)" rx="4"/>`;
  s += `<text x="${scaleX(36.5)}" y="${scaleY(72)}" class="zone-label" text-anchor="middle">Budget</text>`;

  // Grid
  for (let x = 30; x <= 60; x += 5) {
    const px = scaleX(x);
    s += `<line x1="${px}" y1="${margin.top}" x2="${px}" y2="${margin.top + h}" class="grid-line"/>`;
    s += `<text x="${px}" y="${margin.top + h + 20}" class="axis-label" text-anchor="middle">${x}</text>`;
  }
  for (let y = 0; y <= 200; y += 50) {
    const py = scaleY(y);
    s += `<line x1="${margin.left}" y1="${py}" x2="${margin.left + w}" y2="${py}" class="grid-line"/>`;
    s += `<text x="${margin.left - 14}" y="${py + 4}" class="axis-label" text-anchor="end">${y}</text>`;
  }

  // Axis titles
  s += `<text x="${margin.left + w/2}" y="${margin.top + h + 46}" class="axis-title" text-anchor="middle">Intelligence Score (AA Index)</text>`;
  s += `<text x="20" y="${margin.top + h/2}" class="axis-title" text-anchor="middle" transform="rotate(-90, 20, ${margin.top + h/2})">Output Speed (tokens/sec)</text>`;

  // Color function
  function getColor(m) {
    if (m.intel >= 55) return '#3b82f6';
    if (m.intel >= 50) return '#6366f1';
    if (m.intel >= 46 && m.speed >= 100) return '#06b6d4';
    if (m.intel >= 46) return '#8b5cf6';
    if (m.price <= 0.50) return '#f59e0b';
    return '#10b981';
  }

  function getGlow(m) {
    const c = getColor(m);
    return c + '4d'; // 30% opacity hex
  }

  // Manual label placement to avoid overlaps
  const labelPlacements = {
    'Gemini 3.1 Pro': { anchor: 'middle', dx: 0, dy: -1 },
    'GPT-5.4': { anchor: 'end', dx: -20, dy: -10 },
    'Claude Opus 4.6': { anchor: 'start', dx: 20, dy: 20 },
    'Claude Sonnet 4.6': { anchor: 'start', dx: 20, dy: -8 },
    'GLM-5.1': { anchor: 'end', dx: -20, dy: 15 },
    'Grok 4.20': { anchor: 'middle', dx: 0, dy: -1 },
    'Gemini 3 Flash': { anchor: 'end', dx: -15, dy: 15 },
    'DeepSeek V3.2': { anchor: 'start', dx: 20, dy: -8 },
    'Nemotron 3': { anchor: 'middle', dx: 0, dy: -1 },
    'gpt-oss-120B': { anchor: 'start', dx: 15, dy: -5 }
  };

  // Draw bubbles
  bubbleModels.forEach(m => {
    const cx = scaleX(m.intel);
    const cy = scaleY(m.speed);
    const r = scaleR(m.price);
    const color = getColor(m);

    // Glow
    s += `<circle cx="${cx}" cy="${cy}" r="${r + 8}" fill="${color}" opacity="0.15"/>`;
    // Main
    s += `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${color}" opacity="0.7" stroke="${color}" stroke-width="2" class="bubble-main"/>`;
    // Highlight
    s += `<circle cx="${cx}" cy="${cy - r*0.15}" r="${r * 0.55}" fill="white" opacity="0.07"/>`;
  });

  // Draw labels with connectors
  bubbleModels.forEach(m => {
    const cx = scaleX(m.intel);
    const cy = scaleY(m.speed);
    const r = scaleR(m.price);
    const color = getColor(m);
    const placement = labelPlacements[m.name];

    let labelX, labelY, connX, connY;

    if (placement.dy === -1) {
      // Above
      labelX = cx + placement.dx;
      labelY = cy - r - 22;
      connX = cx;
      connY = cy - r - 4;
    } else if (placement.dy < 0) {
      // Above with offset
      labelX = cx + placement.dx;
      labelY = cy + placement.dy * 3 - r;
      connX = cx;
      connY = cy - r - 2;
    } else {
      // Below or side
      labelX = cx + placement.dx;
      labelY = cy + r + 18;
      connX = cx + (placement.dx > 0 ? r + 2 : -r - 2);
      connY = cy;
    }

    // Connector line
    s += `<line x1="${cx}" y1="${cy - r - 2}" x2="${labelX}" y2="${labelY + 6}" stroke="${color}" stroke-width="1" opacity="0.4"/>`;

    // Label background
    const textWidth = m.name.length * 7 + 16;
    const bgX = placement.anchor === 'end' ? labelX - textWidth : placement.anchor === 'middle' ? labelX - textWidth/2 : labelX;
    s += `<rect x="${bgX}" y="${labelY - 12}" width="${textWidth}" height="28" fill="#0b0d13" opacity="0.85" rx="3"/>`;

    // Name label
    s += `<text x="${labelX}" y="${labelY}" class="label-name" text-anchor="${placement.anchor}" fill="${color}">${m.name}</text>`;
    // Stats
    s += `<text x="${labelX}" y="${labelY + 13}" class="label-stats" text-anchor="${placement.anchor}">I:${m.intel} S:${m.speed} P:$${m.price.toFixed(2)}</text>`;
  });

  // Price legend
  const lx = margin.left + w - 90;
  const ly = margin.top + 10;
  s += `<text x="${lx}" y="${ly}" class="price-legend-title">Bubble = Price</text>`;
  [0.30, 3.0, 10.0].forEach((p, i) => {
    const r = scaleR(p);
    const cy = ly + 28 + i * 55;
    s += `<circle cx="${lx + 22}" cy="${cy}" r="${r}" fill="none" stroke="#2d3348" stroke-width="1" stroke-dasharray="3,3"/>`;
    s += `<text x="${lx + 22}" y="${cy + 4}" class="price-legend-text" text-anchor="middle" fill="#475569">$${p.toFixed(2)}</text>`;
  });

  svg.innerHTML = s;
})();
</script>
</body>
