const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 2400, height: 3400 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Check bubble chart label positions
  const labels = await page.evaluate(() => {
    const texts = document.querySelectorAll('#bubble-chart .label-name');
    return Array.from(texts).map(t => ({
      text: t.textContent,
      x: parseFloat(t.getAttribute('x')),
      y: parseFloat(t.getAttribute('y')),
      anchor: t.getAttribute('text-anchor'),
      bbox: t.getBBox()
    }));
  });
  console.log('Bubble labels:', JSON.stringify(labels, null, 2));

  // Check for overlapping bounding boxes
  const overlaps = [];
  for (let i = 0; i < labels.length; i++) {
    for (let j = i + 1; j < labels.length; j++) {
      const a = labels[i].bbox;
      const b = labels[j].bbox;
      if (a && b && a.width > 0 && b.width > 0) {
        const overlapX = Math.max(0, Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x));
        const overlapY = Math.max(0, Math.min(a.y + a.height, b.y + b.height) - Math.max(a.y, b.y));
        if (overlapX > 5 && overlapY > 5) {
          overlaps.push({ a: labels[i].text, b: labels[j].text, overlapX, overlapY });
        }
      }
    }
  }
  console.log('Overlaps:', JSON.stringify(overlaps, null, 2));

  await browser.close();
})();
"

